const VOICE_DATA = {"file":"voice/voices.mp3","lines":{"c1":{"who":"AKURO","text":"Tell me, boy...","mono":false,"off":0.25,"dur":1.131,"env":"0014599797887447899755543321000000"},"c2":{"who":"AKURO","text":"...what is it you want to break?","mono":false,"off":1.7807,"dur":1.6,"env":"003577976864357424674678763223246664321000000000"},"c3":{"who":"TAKUTO","text":"Everything that's in the way.","mono":false,"off":3.7807,"dur":1.557,"env":"06962597114966655887315356655458664111000000000"},"e1":{"who":"TAKUTO","text":"Two-fourteen. Last freight of the night.","mono":true,"off":5.738,"dur":2.005,"env":"0236511169830314444322223566433100355443123344432100000000000"},"e2":{"who":"TAKUTO","text":"Same crossing. Same bell.","mono":true,"off":8.1433,"dur":1.728,"env":"0011866654111798742224321100124655554246432100000000"},"e3":{"who":"TAKUTO","text":"Same cat.","mono":true,"off":10.2713,"dur":0.917,"env":"0022697766312797532100000000"},"e4":{"who":"TAKUTO","text":"It was Haruki's cat first. He fed it every night on his way home.","mono":true,"off":11.5887,"dur":4.373,"env":"056346532127998666520110333332301254410011277531112310000000000003421189848523562244454555433101344433212433332245542110000000000000"},"e5":{"who":"TAKUTO","text":"Two years now.","mono":true,"off":16.362,"dur":0.981,"env":"132753478996324665432110000000"},"e6":{"who":"TAKUTO","text":"So I bring the cat food. Somebody has to.","mono":true,"off":17.7433,"dur":2.752,"env":"00247798932776664125765101115654322110000000124896657765543345655343002210000000000"},"e7":{"who":"TAKUTO","text":"Tuna. The expensive kind. Don't tell anyone.","mono":false,"off":20.8953,"dur":2.901,"env":"0317766664146784145204765233521023667643221100000000397530426777424554433211100000000000"},"e8":{"who":"TAKUTO","text":"Grandma used to say I was born to carry things for other people.","mono":true,"off":24.1967,"dur":4.011,"env":"0288999976797775433566451134544476655300366644532111677876544122101155554400055433332311352045344201133300111000000000000"},"e9":{"who":"TAKUTO","text":"...What is it?","mono":false,"off":28.6073,"dur":0.875,"env":"002359858643254320000000000"},"e10":{"who":"TAKUTO","text":"The bell... There's no train.","mono":true,"off":29.882,"dur":1.664,"env":"03321999976530005543325655420332354432110000000000"},"e11":{"who":"TAKUTO","text":"...Okay. No.","mono":false,"off":31.946,"dur":1.067,"env":"00389403289865566666432110000000"},"e12":{"who":"???","text":"Don't come near it!","mono":false,"off":33.4127,"dur":1.173,"env":"053995102336988877775422210240000000"},"e13":{"who":"TAKUTO","text":"Hey!","mono":false,"off":34.986,"dur":0.576,"env":"003999865432100000"},"e14":{"who":"TAKUTO","text":"Get down!","mono":false,"off":35.962,"dur":0.768,"env":"026400397665432211000000"},"a1":{"who":"TAKUTO","text":"...Two moons.","mono":true,"off":37.13,"dur":0.981,"env":"000347986689987543321221000000"},"a2":{"who":"TAKUTO","text":"Okay. That's new.","mono":true,"off":38.5113,"dur":1.173,"env":"268822269998279831434675421010000000"},"a3":{"who":"TAKUTO","text":"And I'm holding... an axe?","mono":true,"off":40.0847,"dur":1.643,"env":"04577876531399886244322100000354346532100233200000"},"a4":{"who":"TAKUTO","text":"Where the hell am I?","mono":true,"off":42.1273,"dur":1.131,"env":"0048557334899775665554211100000000"},"a5":{"who":"NEMU","text":"Hnnnaaah... Oh. You're alive. Neat.","mono":false,"off":43.658,"dur":2.453,"env":"02550144113555420010000000000006996432014444343332211000000245642100022000"},"a6":{"who":"TAKUTO","text":"You were lying on train tracks a minute ago.","mono":false,"off":46.5113,"dur":2.304,"env":"0144794588887765455532315555541322654302434554442411454321000000000000"},"a7":{"who":"NEMU","text":"Mm. I'm very good at that.","mono":false,"off":49.2153,"dur":1.941,"env":"02488888775531000000001399932677676103775430024322100041000"},"a8":{"who":"NEMU","text":"Lying places. Getting squished.","mono":false,"off":51.5567,"dur":2.368,"env":"002799999874040555422222221221000000000003799387743332117742102333102000"},"a9":{"who":"TAKUTO","text":"Where is this?","mono":false,"off":54.3247,"dur":1.003,"env":"0267999899642159752122110000000"},"a10":{"who":"NEMU","text":"The Barrow Fields. Edge of the Ashen March.","mono":false,"off":55.7273,"dur":3.157,"env":"01307977766641111465431000002320000000000000000049996213322410552047753433245555433211000232100"},"a11":{"who":"NEMU","text":"You fell out of the sky.","mono":false,"off":59.2847,"dur":1.472,"env":"006721117998753027974400145341365432110000000"},"a12":{"who":"NEMU","text":"People like you have a name here. Skyfallen.","mono":false,"off":61.1567,"dur":3.157,"env":"02269105886678860021773467166778888751134321100000000000000000000001345245999831125332221100000"},"a13":{"who":"TAKUTO","text":"There are others?","mono":false,"off":64.714,"dur":0.981,"env":"006788885169927653322221000000"},"a14":{"who":"NEMU","text":"A few. Most of them land worse.","mono":false,"off":66.0953,"dur":2.197,"env":"031111179842000000000028996340440034543334555544420153211002332100"},"a15":{"who":"TAKUTO","text":"...I'll take that as a compliment.","mono":false,"off":68.6927,"dur":1.707,"env":"0027981348995100488656544411146652134322100000000000"},"a16":{"who":"NEMU","text":"...Hey.","mono":false,"off":70.7993,"dur":0.683,"env":"011112998653321000000"},"a17":{"who":"NEMU","text":"Where did you get that axe?","mono":false,"off":71.882,"dur":1.365,"env":"00595782458424851014654103663210012332000"},"a18":{"who":"TAKUTO","text":"It was sticking out of a grave. I grabbed it on the way down.","mono":false,"off":73.6473,"dur":3.413,"env":"0463657631990135666663252126877643211000000000000047732139999993236545555554354443246654211100000000000"},"a19":{"who":"NEMU","text":"That's the Headsman's Axe.","mono":false,"off":77.4607,"dur":1.429,"env":"0168503205843797142466544302774210002121000"},"a20":{"who":"NEMU","text":"It's been stuck in that grave for three hundred years.","mono":false,"off":79.29,"dur":3.371,"env":"033031049763222203763100125544443000114443211000000000000000000004300115774127552332012332100002321000"},"a21":{"who":"NEMU","text":"People tried pulling it out with horses.","mono":false,"off":83.0607,"dur":2.688,"env":"010750255302311676532111010000000000218999877626665431001311025553333211000222100"},"a22":{"who":"TAKUTO","text":"...It was loose.","mono":false,"off":86.1487,"dur":0.939,"env":"04664653345798632112110000000"},"a23":{"who":"NEMU","text":"WHY WAS IT LOOSE?!","mono":false,"off":87.4873,"dur":1.237,"env":"00279984289535620048974201333310000000"},"a24":{"who":"NEMU","text":"Rifts open in the sky. Things crawl out.","mono":false,"off":89.1247,"dur":3.008,"env":"0089610112320089840034332345444330343221110000000000000000000498764401146543343321100020000"},"a25":{"who":"NEMU","text":"We call them Fiends.","mono":false,"off":92.5327,"dur":1.259,"env":"00750434988814865211168764321112333100"},"a26":{"who":"NEMU","text":"Swords don't bite them. Arrows bounce off.","mono":false,"off":94.1913,"dur":3.157,"env":"01223666766303314674100555430001211110000000000000000000015997666543430255554313333221110000000"},"a27":{"who":"NEMU","text":"Normal people can't do anything but run.","mono":false,"off":97.7487,"dur":2.773,"env":"005788776530021342021100000000002117631053540069765200123221000002310026543210000000"},"a28":{"who":"NEMU","text":"Unless you have a Brand.","mono":false,"off":100.922,"dur":1.451,"env":"02998788723333313632461051045665421000021000"},"a29":{"who":"NEMU","text":"A mark on your soul. It wakes up when you're about to die... if you have one.","mono":false,"off":102.7727,"dur":5.333,"env":"0137778778653000101986565454434432200000000000000000000000000000047200699502333367510014776666633654200423045543322110000000000000001611136323455541101111000000"},"a30":{"who":"NEMU","text":"Branded people become Hunters. They hunt Fiends for the Guild.","mono":false,"off":108.506,"dur":4.181,"env":"025788864452001205301222100330213544211166522411000024320000000000000000000001431299521000028998654323420040420354321100010000"},"a31":{"who":"TAKUTO","text":"And people without one?","mono":false,"off":113.0873,"dur":1.387,"env":"026613367501998357437888631344321000000000"},"a32":{"who":"NEMU","text":"Get very good at running.","mono":false,"off":114.874,"dur":1.472,"env":"033721111699878840032698744300287742210000000"},"a33":{"who":"NEMU","text":"Mine's called Nine Lives.","mono":false,"off":116.746,"dur":1.728,"env":"0036999864452032676600056987776443443321100001633000"},"a34":{"who":"NEMU","text":"I can die nine times. I've used six.","mono":false,"off":118.874,"dur":3.243,"env":"02440328974587667765557666665331234432211100332000000000000000000049921159974330132326310022221000"},"a35":{"who":"TAKUTO","text":"Six.","mono":false,"off":122.5167,"dur":0.619,"env":"0012599741111010000"},"a36":{"who":"NEMU","text":"Don't make the face.","mono":false,"off":123.5353,"dur":1.216,"env":"0479974128873010341113643211012221000"},"a37":{"who":"TAKUTO","text":"I'm not making a face.","mono":false,"off":125.1513,"dur":1.365,"env":"15667699943674115454110387531112221000000"},"a38":{"who":"NEMU","text":"You're making it with your eyes.","mono":false,"off":126.9167,"dur":1.643,"env":"00498989995022565443010042124410476432100002332000"},"a39":{"who":"TAKUTO","text":"That thing at the crossing. Was it chasing you?","mono":false,"off":128.9593,"dur":2.581,"env":"005992001976673052124899633233221100000025734720244387543324443322110000000000"},"a40":{"who":"NEMU","text":"I was digging for grave silver. It woke up. Shieldbearers don't wake up.","mono":false,"off":131.9407,"dur":5.355,"env":"00267445321049931565441113100215665555124232443210211100000000000000000002610067740315321100110000000000000000002343699751046443232212330357631145410233210001000"},"a41":{"who":"NEMU","text":"Then the ground opened. Rifts open in the sky... not into other worlds.","mono":false,"off":137.6953,"dur":5.525,"env":"0158766462114666554443401553003100001100000000000000000000002897310101223000278730034433245433432202443322111000000000000000000037655423544220275154213322100000233100"},"a42":{"who":"NEMU","text":"Somebody opened that one.","mono":false,"off":143.6207,"dur":1.835,"env":"01233788846655233100000000049840246542444310011111000000"},"a43":{"who":"TAKUTO","text":"...You hear that?","mono":false,"off":145.8553,"dur":0.917,"env":"0035422678944765321000000000"},"a44":{"who":"NEMU","text":"A bell. There are no bells out here.","mono":false,"off":147.1727,"dur":2.048,"env":"01410997642100000000013169878999610866544454332203114221110000"},"b1":{"who":"NEMU","text":"Run. I mean it this time.","mono":false,"off":149.6207,"dur":1.685,"env":"004998754200000035876689966300243434141322111000000"},"b2":{"who":"TAKUTO","text":"You said that at the crossing.","mono":false,"off":151.706,"dur":1.472,"env":"013332298521666544013001455542212110000000000"},"b3":{"who":"NEMU","text":"And you didn't listen! I only have three left!","mono":false,"off":153.578,"dur":2.837,"env":"00034553681540258443311210000000000000000002563069888762245521101136553333211000002000"},"b4":{"who":"TAKUTO","text":"Then stay behind me.","mono":false,"off":156.8153,"dur":1.387,"env":"005665342079876218522256655432210000000000"},"b5":{"who":"NEMU","text":"Don't hit the shield! Nothing breaks the shield!","mono":false,"off":158.602,"dur":2.773,"env":"032641113930024443326654211010000000000000016997311887643665113200444315432110010000"},"b6":{"who":"TAKUTO","text":"Then what do I hit?!","mono":false,"off":161.7753,"dur":1.216,"env":"0045555994014667754313553100121000000"},"b7":{"who":"NEMU","text":"Nothing! We run!","mono":false,"off":163.3913,"dur":1.045,"env":"00698311688741006741665321000000"},"b8":{"who":"TAKUTO","text":"Can't... get up...","mono":true,"off":164.8367,"dur":1.301,"env":"0012488787630121498667864300000000000000"},"b9":{"who":"NEMU","text":"Hey! Ugly!","mono":false,"off":166.538,"dur":0.896,"env":"001577642001895223331100000"},"b10":{"who":"NEMU","text":"Over here!","mono":false,"off":167.834,"dur":0.789,"env":"039822642217875422100000"},"b11":{"who":"TAKUTO","text":"Wait!","mono":false,"off":169.0233,"dur":0.555,"env":"02798654101100000"},"b12":{"who":"TAKUTO","text":"Born to carry things for other people.","mono":true,"off":169.978,"dur":2.432,"env":"0116999887535401257766552110665444434213541553553011344200232110000000000"},"b13":{"who":"TAKUTO","text":"Groceries. Grudges. Blame.","mono":true,"off":172.81,"dur":2.027,"env":"0003799843323344432200147874212443220003455543210000000000000"},"b14":{"who":"TAKUTO","text":"Not this. I'm not carrying this one.","mono":true,"off":175.2367,"dur":2.261,"env":"01346785000489633321003444454310114444443333233231023210000000000000"},"b15":{"who":"AKURO","text":"Finally.","mono":false,"off":177.898,"dur":0.875,"env":"002499767576554554211000000"},"b16":{"who":"AKURO","text":"Three hundred years in the dirt, and this is who pulls me out?","mono":false,"off":179.1727,"dur":3.968,"env":"000145675543358854369532347775788532245555421368898542000000245554567743333211356433224431001355454213454445543221000000"},"b17":{"who":"TAKUTO","text":"Who are you?","mono":false,"off":183.5407,"dur":0.875,"env":"000576997533567431110000000"},"b18":{"who":"AKURO","text":"The reason the axe was stuck.","mono":false,"off":184.8153,"dur":1.792,"env":"013995566676534766575435666421125432221477642100000000"},"b19":{"who":"AKURO","text":"Tell me, boy. What is it you want to break?","mono":false,"off":187.0073,"dur":2.411,"env":"0134577989986446889986553201235886995554223686566522221477653320001100000"},"b20":{"who":"TAKUTO","text":"Everything that's in the way.","mono":false,"off":189.818,"dur":1.557,"env":"06962597114966655887315356655458664111000000000"},"b21":{"who":"AKURO","text":"...Good answer.","mono":false,"off":191.7753,"dur":1.088,"env":"013379877645777643334654432100000"},"b22":{"who":"TAKUTO","text":"It was in the way.","mono":false,"off":193.2633,"dur":1.131,"env":"0652496458787775458886311100000000"},"b23":{"who":"NEMU","text":"Hnnaaah... Ow.","mono":false,"off":194.794,"dur":1.493,"env":"027640343125555422112000000000005986421000000"},"b24":{"who":"TAKUTO","text":"You were dead.","mono":false,"off":196.6873,"dur":0.896,"env":"013545742189887532100000000"},"b25":{"who":"NEMU","text":"Mm. That's seven. Two left.","mono":false,"off":197.9833,"dur":2.155,"env":"02697777766442100145300333256510311000000000431965343321100002000"},"b26":{"who":"TAKUTO","text":"Don't do that again.","mono":false,"off":200.538,"dur":1.237,"env":"01897430367628765442135543210000000000"},"b27":{"who":"NEMU","text":"You're making the face.","mono":false,"off":202.1753,"dur":1.237,"env":"00598898970316654431114542100023221000"},"b28":{"who":"TAKUTO","text":"I'm making it with my whole face this time.","mono":false,"off":203.8127,"dur":2.539,"env":"03777668898201355555311330365553126988621116654334203334112554311000000000000"},"b29":{"who":"TAKUTO","text":"...I never asked your name.","mono":false,"off":206.7513,"dur":1.451,"env":"00357778953997666463024455555432100000000000"},"b30":{"who":"NEMU","text":"Nemu.","mono":false,"off":208.602,"dur":0.875,"env":"000599988778753211110000000"},"b31":{"who":"NEMU","text":"And you're the idiot who pulled out the Headsman's Axe.","mono":false,"off":209.8767,"dur":2.965,"env":"00465457662240005971321100001000000000000410213553254320132124412303433231133210001122100"},"b32":{"who":"TAKUTO","text":"Takuto. Kirishima Takuto.","mono":false,"off":213.242,"dur":2.283,"env":"036630054126987532100014434354244444443002443101320223432110000000000"},"b33":{"who":"SIEG","text":"Well, well, well.","mono":false,"off":215.9247,"dur":1.429,"env":"0697665666787765556676300279777644432100000"},"b34":{"who":"SIEG","text":"A Shieldbearer's shield. Broken in one swing.","mono":false,"off":217.754,"dur":3.008,"env":"0597444797776656776777643333676676544431000000000998741397656777766766654331488654322110000"},"b35":{"who":"SIEG","text":"Twelve years I've been hunting. Never seen that.","mono":false,"off":221.162,"dur":3.179,"env":"024976655766665555542100004677532766652276553267544331000000008977457653322777776545443210110000"},"b36":{"who":"SIEG","text":"Nice axe, kid. Mind telling me where you got it?","mono":false,"off":224.7407,"dur":3.093,"env":"288666643102676420133001597764342000000000697666666413296556666665566566653376655423421110000"},"b37":{"who":"TAKUTO","text":"It was loose.","mono":false,"off":228.234,"dur":0.917,"env":"0443553244698642111110000000"},"b38":{"who":"NEMU","text":"He keeps saying that.","mono":false,"off":229.5513,"dur":1.451,"env":"00094042796044335898766554554321002100000000"},"b39":{"who":"SIEG","text":"Ha! It was loose, he says.","mono":false,"off":231.402,"dur":1.792,"env":"017987666641047458867999877762210019963278655433210000"},"b40":{"who":"SIEG","text":"You two had better come with me. Because that...","mono":false,"off":233.594,"dur":2.795,"env":"088741327765566677554256546652012765555664105654443100000005842997544776543202211000"},"b41":{"who":"SIEG","text":"...is not supposed to stay open.","mono":false,"off":236.7887,"dur":1.984,"env":"069878976563113286219766764101475320577652367762055332210000"},"b42":{"who":"AKURO","text":"We're going to have so much fun, you and I.","mono":false,"off":239.1727,"dur":2.603,"env":"0149736887643454577633444697756743321136765552321013489865664223555432211000000"},"s1":{"who":"SABLE","text":"One fell through.","mono":false,"off":242.1753,"dur":1.856,"env":"00022479775221246443223311133322222100000000000000000000"},"s2":{"who":"SABLE","text":"...Good.","mono":false,"off":244.4313,"dur":1.045,"env":"01211442137976432220111111100000"},"p1":{"who":"TAKUTO","text":"Next time: the Hunters' Guild.","mono":false,"off":245.8767,"dur":1.728,"env":"0258821530399977653354247632365331158863211000000000"},"p2":{"who":"TAKUTO","text":"A test that reads my rank as ERROR...","mono":false,"off":248.0047,"dur":2.133,"env":"0310327973310652124442113544432444443013322103444321100000000000"},"p3":{"who":"TAKUTO","text":"...and a girl with a red scarf who hates me on sight.","mono":false,"off":250.538,"dur":2.859,"env":"00046674226999997435315323656412442036776431103322354302134333332233254210000000000000"},"p4":{"who":"TAKUTO","text":"Why does she have my hair?","mono":false,"off":253.7967,"dur":1.493,"env":"004798938555345557721355444213654211000000000"},"p5":{"who":"TAKUTO","text":"Episode two. Branded.","mono":false,"off":255.69,"dur":1.621,"env":"0451143349974103327653211000026655654322110000000"}}};
